export type TrustParams = { cwd: string, 
/**
 * None reads the current decision.
 */
allow: boolean | null, };

export type TrustResult = { 
/**
 * None when the directory has no decision.
 */
allowed: boolean | null, };

export type Turn = { id: TurnId, status: TurnStatus, items: Array<Item>, 
/**
 * Unix milliseconds; zero in older clients' data.
 */
started_at: number, 
/**
 * Unix milliseconds of the turn's last entry, once it has ended.
 */
ended_at?: number | null, };

export type TurnChanges = { changes: Array<FileChange>, 
/**
 * Whether the turn has been undone.
 */
reverted: boolean, };

export type TurnId = string;

export type TurnParams = { thread_id: ThreadId, item_id: string, };

export type TurnStatus = "in_progress" | "completed" | "interrupted" | "failed";

export type UndoCheck = { safe: Array<string>, unsafe: Array<string>, ignored: Array<string>, };

export type Version = "2.0";

export type WriteParams = { root: string, path: string, text: string, 
/**
 * Fails when the file's hash differs, or it exists while this is empty; None overwrites.
 */
expected: string | null, };

export type WriteResult = { hash: string, };
